from src.calculator import add, divide, parse_int, normalize_name, clamp


def test_add():
    assert add(1, 2) == 3


def test_divide():
    assert divide(6, 2) == 3


def test_divide_by_zero_returns_none():
    assert divide(1, 0) is None


def test_parse_int_empty_string_returns_none():
    assert parse_int("") is None


def test_normalize_name_none_returns_empty_string():
    assert normalize_name(None) == ""


def test_clamp_below_low_returns_low():
    assert clamp(5, 10, 20) == 10


def test_clamp_above_high_returns_high():
    assert clamp(25, 10, 20) == 20


def test_clamp_in_range_returns_value():
    assert clamp(15, 10, 20) == 15
